CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS colaboradores (id SERIAL PRIMARY KEY, nombre VARCHAR(150) NOT NULL, departamento VARCHAR(100) NOT NULL, puesto VARCHAR(120) NOT NULL, fecha_ingreso DATE NOT NULL, jefe_id INTEGER REFERENCES colaboradores(id), estado VARCHAR(30) NOT NULL DEFAULT 'ACTIVO');
CREATE TABLE IF NOT EXISTS usuarios (id SERIAL PRIMARY KEY, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, rol VARCHAR(20) NOT NULL DEFAULT 'COLABORADOR', colaborador_id INTEGER UNIQUE REFERENCES colaboradores(id), activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS saldos_vacaciones (id SERIAL PRIMARY KEY, colaborador_id INTEGER NOT NULL REFERENCES colaboradores(id), periodo VARCHAR(9) NOT NULL, dias_asignados INTEGER NOT NULL, dias_tomados INTEGER NOT NULL, dias_disponibles INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS solicitudes (id SERIAL PRIMARY KEY, colaborador_id INTEGER NOT NULL REFERENCES colaboradores(id), tipo VARCHAR(50) NOT NULL, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE', aprobador_id INTEGER REFERENCES colaboradores(id), creada_en TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS incapacidades (id SERIAL PRIMARY KEY, colaborador_id INTEGER NOT NULL REFERENCES colaboradores(id), tipo VARCHAR(60) NOT NULL, fecha_inicio DATE NOT NULL, dias INTEGER NOT NULL, entidad VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS movimientos_personal (id SERIAL PRIMARY KEY, colaborador_id INTEGER NOT NULL REFERENCES colaboradores(id), tipo VARCHAR(30) NOT NULL, fecha DATE NOT NULL, motivo VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS documentos (id SERIAL PRIMARY KEY, drive_file_id VARCHAR(120) UNIQUE NOT NULL, nombre VARCHAR(255) NOT NULL, version VARCHAR(30) NOT NULL, fecha_vigencia DATE NOT NULL, responsable VARCHAR(150) NOT NULL, drive_url VARCHAR(500) NOT NULL, contenido_hash VARCHAR(64) NOT NULL, indexado_en TIMESTAMP, eliminado BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS document_chunks (id SERIAL PRIMARY KEY, documento_id INTEGER NOT NULL REFERENCES documentos(id), seccion VARCHAR(255) NOT NULL, contenido TEXT NOT NULL, embedding vector(1536), metadata_json JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS consultas_chat (id SERIAL PRIMARY KEY, colaborador_id INTEGER REFERENCES colaboradores(id), pregunta TEXT NOT NULL, intencion VARCHAR(40) NOT NULL, agente VARCHAR(50) NOT NULL, documentos_citados JSONB NOT NULL DEFAULT '[]', resuelta BOOLEAN NOT NULL DEFAULT FALSE, escalada BOOLEAN NOT NULL DEFAULT FALSE, latencia_ms INTEGER NOT NULL, fecha TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reportes_diarios (id SERIAL PRIMARY KEY, fecha DATE UNIQUE NOT NULL, datos_json JSONB NOT NULL, resumen_texto TEXT NOT NULL, generado_por VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS escalamientos (id SERIAL PRIMARY KEY, consulta_id INTEGER NOT NULL REFERENCES consultas_chat(id), motivo VARCHAR(255) NOT NULL, estado VARCHAR(30) NOT NULL DEFAULT 'ABIERTO', creada_en TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS auditoria_ia (id SERIAL PRIMARY KEY, agente VARCHAR(50) NOT NULL, accion VARCHAR(100) NOT NULL, detalle_json JSONB NOT NULL DEFAULT '{}', creada_en TIMESTAMP NOT NULL DEFAULT NOW());
